    {"id":"book-001","isbn":"9780131103627","title":"The Art of Computer Programming","author":"Donald E. Knuth","category":"Computing","totalCopies":3,"availableCopies":2},
    {"id":"book-002","isbn":"9780321751041","title":"Introduction to Algorithms","author":"Thomas H. Cormen et al.","category":"Computing","totalCopies":4,"availableCopies":4}],
  "issues":[{"id":"issue-001","bookId":"book-001","bookTitle":"The Art of Computer Programming","studentId":"2024BCS1021","studentName":"Aarav Sharma","issuedAt":"2026-10-28","dueAt":"2026-11-18"}],
  "courseOfferings":[],"students":[],"enrollments":[],"attendanceSessions":[],"roomAllocations":[]
}
$seed$::jsonb)
ON CONFLICT (id) DO UPDATE SET payload=EXCLUDED.payload,updated_at=now();

COMMIT;

